	GetSymbol(context.Context, *lexora.GetSymbolRequest) (*shared.Symbol, error)
	GetWord(context.Context, *lexora.GetWordRequest) (*shared.Word, error)
	ListReferents(context.Context, *lexora.ListReferentsRequest) (*lexora.ListReferentsResponse, error)
