	CreateReferent(context.Context, *lexora.CreateReferentRequest) (*shared.Referent, error)
	CreateSymbol(context.Context, *lexora.CreateSymbolRequest) (*shared.Symbol, error)
	CreateWord(context.Context, *lexora.CreateWordRequest) (*shared.Word, error)
	CreateWordAttributes(context.Context, *lexora.CreateWordAttributesRequest) (*shared.WordAttributes, error)
	// UPDATE
	UpdateReferent(context.Context, *lexora.UpdateReferentRequest) (*shared.Referent, error)
	UpdateSymbol(context.Context, *lexora.UpdateSymbolRequest) (*shared.Symbol, error)
	UpdateWord(context.Context, *lexora.UpdateWordRequest) (*shared.Word, error)
	UpdateWordAttributes(context.Context, *lexora.UpdateWordAttributesRequest) (*shared.WordAttributes, error)
	// DELETE
	DeleteReferent(context.Context, *lexora.DeleteReferentRequest) (*shared.Referent, error)
	DeleteSymbol(context.Context, *lexora.DeleteSymbolRequest) (*shared.Symbol, error)
	DeleteWord(context.Context, *lexora.DeleteWordRequest) (*shared.Word, error)
	DeleteWordAttributes(context.Context, *lexora.DeleteWordAttributesRequest) (*shared.WordAttributes, error)
	// LINKING OPERATIONS
	LinkSymbolToReferent(context.Context, *lexora.LinkSymbolToReferentRequest) (*lexora.LinkSymbolToReferentResponse, error)
	LinkWordToSymbol(context.Context, *lexora.LinkWordToSymbolRequest) (*lexora.LinkWordToSymbolResponse, error)
	SetSymbolLemma(context.Context, *lexora.SetSymbolLemmaRequest) (*lexora.SetSymbolLemmaResponse, error)
	UnlinkSymbolFromReferent(context.Context, *lexora.UnlinkSymbolFromReferentRequest) (*lexora.UnlinkSymbolFromReferentResponse, error)
	UnlinkWordFromSymbol(context.Context, *lexora.UnlinkWordFromSymbolRequest) (*lexora.UnlinkWordFromSymbolResponse, error)
	ListAllLinkedReferents(context.Context, *lexora.ListAllLinkedReferentsRequest) (*lexora.ListAllLinkedReferentsResponse, error)
	ListAllLinkedSymbols(context.Context, *lexora.ListAllLinkedSymbolsRequest) (*lexora.ListAllLinkedSymbolsResponse, error)
	// text analysis
	AnalyzeTextAndAddToSuggestions(context.Context, *lexora.AnalyzeTextAndAddToSuggestionsRequest) (*lexora.AnalyzeTextAndAddToSuggestionsResponse, error)
	ListAllWordSuggestion(context.Context, *lexora.ListAllWordSuggestionRequest) (*lexora.ListAllWordSuggestionResponse, error)
